-- Lock chat media to private bucket access.
-- Files are now served through signed URLs generated by the app.
-- Rollback: set storage.buckets.public=true for chat-media and restore prior read policy if you intentionally return to publicly readable media.

update storage.buckets
set public = false
where id = 'chat-media';

drop policy if exists "chat_media_select_public" on storage.objects;
drop policy if exists "chat_media_select_authenticated" on storage.objects;
create policy "chat_media_select_authenticated"
  on storage.objects for select
  to authenticated
  using (bucket_id = 'chat-media');
